.text:00401041                 xor     esi, esi
.text:00401043
.text:00401043 loc_401043:                                ; CODE XREF:
.text:00401043                 push    esi
.text:00401044                 push    offset _Format  ; "%d"
.text:00401049                 call    _printf
.text:0040104E                 inc     esi
.text:0040104F                 add     esp, 8
.text:00401052                 cmp     esi, 0Ah
.text:00401055                 jl      short loc_401043
.text:00401057                 pop     esi
.text:00401058                 xor     eax, eax
.text:0040105A                 retn
.text:0040105A _main          endp
```

### while与for

在release里面被优化成 if判断加do-while结构：

```c
int i = 0;
while (i < 10) {
    printf("%d", i);
    i++;
} ;
等价于：
if (i < 10) {
    do {
        printf("%d", i);
        i++;
    }
    while (i < 10);
}
```

### continue

汇编表现为跳回循环的判断位置

```c
for (int i = argc; i < 10; i++) {
    if (i == 3) {
        continue;
    }
```

```asm
loc_401050:
			cmp     esi, 3
			jz      short loc_401063
			push    esi
			push    offset _Format  ; "%d"
			call    _printf
			add     esp, 8

loc_401063:
			inc     esi
			cmp     esi, 0Ah
			jl      short loc_401050
```

### Break

汇编表现为跳出整个循环范围

```c
for (int i = argc; i < 10; i++) {
    if (i == 3) {
        Break;
    }
```

